    PRIMARY KEY (ITEMN)
);
CREATE TABLE ITL (
    ITEMN INT,
    WKCEN INT,
    LOCAN INT
);

counterexample:
-- There is no counterexample because, under the given schema and constraints, Q1 and Q2 are equivalent.
-- For demonstration, here is some sample data that yields the same result for both queries:

INSERT INTO ITP (ITEMN, PONUM) VALUES (1, 100);
INSERT INTO ITP (ITEMN, PONUM) VALUES (2, 200);

-- In ITL, ITEMN = 1 meets the condition; ITEMN = 2 does not
INSERT INTO ITL (ITEMN, WKCEN, LOCAN) VALUES (1, 468, 0);

-- A duplicate row in ITL that still meets the condition (this does not change the results of either query)
INSERT INTO ITL (ITEMN, WKCEN, LOCAN) VALUES (1, 468, 0);

-- A row that does not satisfy the condition for ITEMN = 2
INSERT INTO ITL (ITEMN, WKCEN, LOCAN) VALUES (2, 123, 9);

-- Running Q1 and Q2 on this data both yield the single ITP row with ITEMN = 1.

