q2:
SELECT DISTINCT *
FROM (
  SELECT * FROM R AS X WHERE X.X > 50
  UNION ALL
  SELECT * FROM R AS Y WHERE Y.X < 200
) AS T;

counterexample:
-- No counterexample exists since the two queries are equivalent. To illustrate this, here is an example set of INSERT statements whose results would be identical under both queries:
INSERT INTO R (X) VALUES (NULL);
INSERT INTO R (X) VALUES (10);
INSERT INTO R (X) VALUES (50);
INSERT INTO R (X) VALUES (100);
INSERT INTO R (X) VALUES (200);
INSERT INTO R (X) VALUES (300);

-- There is no valid counterexample under the given schema and query definitions because Q1 and Q2 are equivalent.
-- For example, these INSERTs demonstrate typical data, but Q1 and Q2 will always yield the same results:
INSERT INTO R (X) VALUES (1);
INSERT INTO R (X) VALUES (0);
INSERT INTO R (X) VALUES (-1);
INSERT INTO R (X) VALUES (NULL);

-- No counterexample exists because the queries are equivalent.
-- For example, even if we insert sample data:
INSERT INTO A (A1, A2) VALUES (1, 10), (2, 20);
INSERT INTO B (B1, B2) VALUES (1, 100), (2, 200);
-- Both Q1 and Q2 will return exactly the join rows (1,10,1,100) and (2,20,2,200).

q2:
SELECT * FROM R1 AS X, R2 AS Y
UNION ALL
SELECT * FROM R1 AS X, R3 AS Y;

schema:
CREATE TABLE R1 (X INT);
CREATE TABLE R2 (X INT);
CREATE TABLE R3 (X INT);

counterexample:
-- No INSERT statements can produce a difference because the queries are equivalent.
-- For example, even if you insert:
INSERT INTO R1 VALUES (1);
INSERT INTO R2 VALUES (10);
INSERT INTO R3 VALUES (20);
-- Q1 returns:
-- (1,10) and (1,20)
-- and Q2 returns exactly the same rows: (1,10) union all (1,20)
-- Thus no counterexample exists.

INSERT INTO R1 (A, B) VALUES (1, 10);
INSERT INTO R1 (A, B) VALUES (2, 10);

INSERT INTO R2 (A, B) VALUES (1, 20);

