schema:
CREATE TABLE COURSE (COURSE_ID INT, TITLE INT, DEPT_NAME INT, CREDITS INT);
CREATE TABLE DEPARTMENT (DEPT_NAME INT, BUILDING INT, BUDGET INT);
CREATE TABLE INSTRUCTOR (ID INT, NAME INT, SALARY INT, DEPT_NAME INT);
CREATE TABLE TEACHES (ID INT, COURSE_ID INT, SEC_ID INT, YEAR INT, SEMESTER INT, INSTRUCTOR INT);
CREATE TABLE SECTION (COURSE_ID INT, SEC_ID INT, YEAR INT, BUILDING INT, ROOM_NUMBER INT, TIME_SLOT_ID INT);
CREATE TABLE TAKES (ID INT, COURSE_ID INT, SEC_ID INT, YEAR INT, GRADE INT);
CREATE TABLE STUDENT (ID INT, NAME INT, DEPT_NAME INT, TOT_CRED INT);

counterexample:
-- Inserting test data so that Q1 and Q2 behave differently

-- Insert three students
INSERT INTO STUDENT (ID, NAME, DEPT_NAME, TOT_CRED) VALUES (1, 101, 10, 30);
INSERT INTO STUDENT (ID, NAME, DEPT_NAME, TOT_CRED) VALUES (2, 102, 10, 30);
INSERT INTO STUDENT (ID, NAME, DEPT_NAME, TOT_CRED) VALUES (3, 103, 10, 30);

-- For student 1, create 2 TAKES rows that join with a SECTION having TIME_SLOT_ID = 0
-- This will yield a group with COUNT = 2 (thus passing Q1) but SUM = 0 (thus failing Q2)
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (1, 1, 1, 2020, 90);
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (1, 1, 1, 2020, 92);
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (1, 1, 2020, 1, 101, 0);

-- For student 2, create 2 TAKES rows that join with a SECTION having TIME_SLOT_ID = 2
-- Here both COUNT and SUM conditions are satisfied
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (2, 2, 1, 2020, 85);
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (2, 2, 1, 2020, 87);
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (2, 1, 2020, 2, 102, 2);

-- For student 3, create 2 TAKES rows that join with a SECTION having TIME_SLOT_ID = 2
-- Here both COUNT and SUM conditions are satisfied too
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (3, 3, 1, 2020, 80);
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (3, 3, 1, 2020, 82);
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (3, 1, 2020, 3, 103, 2);

